// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address owner0;

    function setUp() public {
        c = new Owned();
        owner0 = address(this);
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        if (actor == owner0) {
            assertTrue(ok && c.owner() == newOwner, "owner's setOwner must succeed and take effect");
        } else {
            assertTrue(!ok && c.owner() == owner0, "non-owner's setOwner must revert and leave owner unchanged");
        }
    }
}
